function display(k,v){if(v==null||v==='')return '—';if(k.endsWith('_at')||['last_login_at','session_expires'].includes(k))return sqlDate(v);if(['active','on_bazaar','on_myket'].includes(k))return Number(v)?'بله':'خیر';if(k==='pro')return Number(v)?'Pro':'رایگان';if(k.includes('price')||k==='amount_toman')return money(v);if(k==='size')return num(Math.round(v/1024))+' KB';return values[v]||catalog.formats?.[v]||(typeof v==='number'?num(v):String(v));}
