async function api(route,data=null,params={}){const url=new URL('../api.php',location.href);url.searchParams.set('r',route);Object.entries(params).forEach(([k,v])=>{if(v!==''&&v!=null)url.searchParams.set(k,v);});const opts={method:data===null?'GET':'POST',headers:{},cache:'no-store',credentials:'omit'};if(token)opts.headers.Authorization='Bearer '+token;if(data instanceof FormData)opts.body=data;else if(data!==null){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data);}let response;try{response=await fetch(url,opts);}catch(e){throw new Error('ارتباط برقرار نشد. اینترنت را بررسی کنید؛ درخواست را با همان دکمه دوباره بفرستید.');}const json=await response.json();if(!json.ok){const e=new Error(json.error?.message||'درخواست ناموفق بود.');e.code=json.error?.code;if(response.status===401){token='';sessionStorage.removeItem('divan_tg_session');}throw e;}$('#sync-state').textContent='آخرین ارتباط: '+dateFmt.format(new Date());return json.data;}
function initTheme(){const isLight=themeChoice==='light'||(themeChoice==='auto'&&tg?.colorScheme==='light');document.body.classList.toggle('light',isLight);tg?.setHeaderColor?.(isLight?'#f4f4eb':'#061a17');tg?.setBackgroundColor?.(isLight?'#f4f4eb':'#061a17');}
