function chart(title,rows,key,labelKey='day'){const max=Math.max(1,...rows.map(r=>Number(r[key])));return `<section class="panel"><h2>${esc(title)}</h2>${rows.length?`<div class="chart">${rows.map(r=>`<button class="bar" style="height:${Math.max(2,Number(r[key])/max*100)}%" data-value="${esc((labelKey==='day'?sqlDate(r[labelKey]+' 08:00:00'):r[labelKey])+' • '+num(r[key]))}" aria-label="${esc(r[labelKey]+' '+num(r[key]))}"></button>`).join('')}</div><div class="chart-info">برای مشاهده مقدار، ستون را لمس کنید.</div>`:'<p class="muted">داده‌ای در این بازه ثبت نشده است.</p>'}</section>`;}
