h+=`<div class="section-head"><h2>دسترسی سریع</h2><a href="#more">همه بخش‌ها ←</a></div><div class="quick-grid">${sections.filter(x=>can(x[1])).slice(0,4).map(([r,p,i])=>`<a href="#${r}" class="quick">${icon(i)}${titleMap[r]}</a>`).join('')}</div>`;
if(d.daily_sales)h+=`<div class="section-head"><h2>روند عملکرد</h2><span class="muted">۳۰ روز اخیر</span></div><div class="panels">${chart('فروش روزانه · تومان',d.daily_sales,'amount')}<section class="panel"><h2>کانال‌های فروش</h2>${d.channels.length?d.channels.map(c=>`<div class="legend-row"><span>${esc(values[c.channel]||c.channel)}<div class="hint">${num(c.count)} خرید</div></span><strong>${money(c.amount)}</strong></div>`).join(''):'<p class="muted">خرید تأییدشده‌ای ثبت نشده است.</p>'}</section></div>${chart('فروش ماهانه · ماه شمسی / تومان',d.monthly_sales,'amount','month')}`;
if(d.registrations)h+=chart('روند ثبت‌نام',d.registrations,'count');
if(d.by_plan)h+=`<div class="panel"><h2>سهم پلن‌های خریداری‌شده</h2>${d.by_plan.map(p=>`<div class="legend-row"><span>${esc(p.title||'پلن نامشخص')} · ${num(p.count)} خرید</span><strong>${money(p.amount)}</strong></div>`).join('')||'<p class="muted">هنوز داده‌ای ثبت نشده.</p>'}</div>`;
if(d.purchase_status)h+=`<div class="panels"><div class="panel"><h2>وضعیت خریدهای فروشگاه</h2>${d.purchase_status.map(p=>`<div class="legend-row">${badge(p.status)}<strong>${num(p.count)}</strong></div>`).join('')}</div><div class="panel"><h2>وضعیت سفارش‌های مستقیم</h2>${d.order_status.map(p=>`<div class="legend-row">${badge(p.status)}<strong>${num(p.count)}</strong></div>`).join('')}</div></div><div class="notice">درآمد، جمع مبالغ ثبت‌شده خریدهای با تأیید نهایی است؛ خرید مستقیم دوباره شمرده نمی‌شود. رکوردهای بدون مبلغ: ${num(d.sales.unknown_amounts)}. این عدد تسویه بانکی یا درآمد خالص پس از کارمزد نیست.</div>`;
